let journal={};try{journal=JSON.parse(localStorage.getItem("faded-garden-journal")||"{}")}catch{}
const R=modules.rules,L=modules.levels,$=id=>document.getElementById(id),colors=['#e18c82','#7c9dce','#e0bc58','#91b29a','#ae8bc3','#e4a46e','#63babb'];let assisted=false,recorded=false,totalMoves=0;let sound=false,audio=null;let idx=0,b,history=[],selected=-1,hints=[],busy=false;for(let i=0;i<L.length;i++)$('level').add(new Option(`${i+1} · ${L[i].name}`,i));function save(){try{localStorage.setItem('faded-garden-release-v1',JSON.stringify({idx,b,history,assisted,recorded,totalMoves}));localStorage.setItem('faded-garden-journal',JSON.stringify(journal));if($('save-status'))$('save-status').textContent='已自动保存 · 可导出存档备份'}catch{if($('save-status'))$('save-status').textContent='保存失败，请导出备份';}}function start(i){assisted=false;recorded=false;totalMoves=0;busy=false;idx=i;b=R.clone(L[i].bottles);history=[];selected=-1;hints=[];draw();save()}function draw(){ $('level').value=idx;renderStory();renderRanks();$('stats').textContent=`第 ${idx+1} / ${L.length} 关 · ${totalMoves} 次倒水`;$('board').replaceChildren();b.forEach((a,i)=>{const btn=document.createElement('button');btn.className='bottle'+(selected===i?' active':'')+(hints.includes(i)?' hint':'')+(a.length===4&&R.isBottleSolved(a,4)?' complete':'');btn.classList.toggle('available',selected>=0&&selected!==i&&R.inspectPour(b,selected,i).ok);btn.setAttribute('aria-pressed',String(selected===i));btn.setAttribute('aria-label',`瓶子 ${i+1}，${a.length} 格水`);a.forEach(c=>{const w=document.createElement('span');w.className='water';w.style.background=colors[c];w.textContent=['●','◆','▲','■','★','＋','♥'][c];btn.append(w)});btn.onclick=()=>click(i);$('board').append(btn)});$('undo').disabled=!history.length||busy;$('hint').disabled=busy||R.isSolved(b);$('next').hidden=!R.isSolved(b)||idx===L.length-1;const done=b.filter(a=>a.length===4&&R.isBottleSolved(a,4)).length;$('progress').max=L[idx].colors;$('progress').value=done;$('progress-label').textContent=`已归好 ${done} / ${L[idx].colors} 种颜色`;$('level').disabled=busy;$('reset').disabled=busy;$('message').textContent=R.isSolved(b)?'漂亮！每一种颜色都找到了自己的瓶子。':selected>=0?'已选中：点击发亮的瓶子倒入，再点原瓶取消。':'选一只瓶子，寻找相同的顶部颜色。'}function click(i){if(busy||R.isSolved(b))return;hints=[];if(selected<0){if(b[i].length){selected=i;buzz(12)}draw();return}if(selected===i){selected=-1;draw();return}const result=R.pour(b,selected,i);if(result.ok){animatePour(selected,i,result.color);totalMoves++;history.push(R.clone(b));b=result.bottles;selected=-1;save();draw();if(R.isSolved(b)){recordWin();celebrate()}}else{buzz([35,30,35]);draw();document.querySelectorAll('.bottle')[i].classList.add('wrong');$('message').textContent=result.reason+'；可以换一个发亮的瓶子。'}}$('level').onchange=e=>{busy=false;start(+e.target.value)};$('undo').onclick=()=>{if(busy)return;b=history.pop()||b;selected=-1;hints=[];save();draw()};$('reset').onclick=()=>{if(!busy&&confirm('重新开始这一关？'))start(idx)};$('next').onclick=()=>start(idx+1);$('hint').onclick=()=>{if(R.isSolved(b))return;assisted=true;save();busy=true;selected=-1;const token=idx,board=JSON.stringify(b),initial=R.same(b,L[idx].bottles),search=modules.solver.createSearch(b,{capacity:4,maxNodes:60000});if(initial){busy=false;hints=L[idx].solution[0];draw();$('message').textContent=`试试：瓶子 ${hints[0]+1} → 瓶子 ${hints[1]+1}`;return}draw();$('message').textContent='正在找路线…';function step(){if(idx!==token||JSON.stringify(b)!==board){busy=false;draw();return}const r=search.step(120);if(r.status==='searching'){setTimeout(step,0);return}busy=false;hints=r.path&&r.path.length?r.path[0]:[];draw();$('message').textContent=hints.length?`试试：瓶子 ${hints[0]+1} → 瓶子 ${hints[1]+1}`:'暂时没找到路线，可以撤销或重来。'}step()};try{const x=JSON.parse(localStorage.getItem('faded-garden-release-v1'));if(x&&Number.isInteger(x.idx)&&L[x.idx]&&R.validateBoard(x.b,L[x.idx].colors,4,9)){idx=x.idx;b=x.b;assisted=x.assisted===true;recorded=x.recorded===true;totalMoves=Number.isInteger(x.totalMoves)?x.totalMoves:x.history?.length||0;history=Array.isArray(x.history)?x.history.filter(a=>R.validateBoard(a,L[idx].colors,4,9)):[]}}catch{}if(b)draw();else start(0);
function buzz(p){if(navigator.vibrate)navigator.vibrate(p)}function animatePour(a,c,color){buzz(18);busy=true;const epoch=idx;setTimeout(()=>{if(idx!==epoch)return;busy=false;draw();const target=document.querySelectorAll('.bottle')[c];if(target){target.classList.add('land');if(b[c].length===4&&R.isBottleSolved(b[c],4)){target.classList.add('new-complete');$('message').textContent=R.isSolved(b)?'全部归位！这一局完成了。':'又归好一种颜色，漂亮！';tone(true)}else{target.classList.add('received');$('message').textContent='倒入成功，继续寻找同色。';tone(false)}}},220)}function tone(win){if(!sound)return;try{const ctx=audio||(audio=new (window.AudioContext||window.webkitAudioContext)());ctx.resume();[0,...(win?[1,2]:[])].forEach((n)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=[523,659,784][n];g.gain.setValueAtTime(.0001,ctx.currentTime+n*.09);g.gain.exponentialRampToValueAtTime(.07,ctx.currentTime+n*.09+.01);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+n*.09+.18);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+n*.09);o.stop(ctx.currentTime+n*.09+.2)})}catch{}}function celebrate(){buzz([30,50,70]);for(let k=0;k<45;k++){const e=document.createElement('i');e.className='confetti';e.style.left=Math.random()*100+'vw';e.style.background=colors[k%7];e.style.animationDelay=Math.random()*.4+'s';document.body.append(e);setTimeout(()=>e.remove(),2100)}}
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'声音：开':'声音：关';$('sound').setAttribute('aria-pressed',String(sound));if(sound)tone(false)};

function renderRanks(){if($('collection'))$('collection').textContent='已修复 '+Object.keys(journal).length+' / 60 处花园';}function recordWin(){if(recorded)return;recorded=true;journal[idx+1]={completed:true,moves:totalMoves,assisted};save();renderRanks();renderStory();}
function renderStory(){const chapter=Math.min(2,Math.floor(idx/20)),titles=['第一章 · 唤醒温室','第二章 · 雾中的溪谷','第三章 · 花园的心脏'],texts=['邮差送来一封没有颜色的信：花园正在忘记春天。你找到九只染色瓶，试着把散落的七种颜色重新归位。','温室亮起了，溪谷却仍被灰雾覆盖。守园人留下字条：别急着倒空手里的颜色，有时空位比色彩更珍贵。','最后的种子藏在花园深处。你已经学会等待、留白与重新选择；这一次，让七种颜色一起回家。'],wins=['温室的玻璃透出暖光，一粒新芽探出头来。','溪水重新映出天空，灰雾正在散去。','沉睡的种子发出光，花园记起了春天。'];const won=R.isSolved(b),done=b.filter(a=>a.length===4&&R.isBottleSolved(a,4)).length;$('story').replaceChildren();const t=document.createElement('h2'),v=document.createElement('p');t.textContent=titles[chapter]+' · '+(idx%20+1)+'/20';v.textContent=won?wins[chapter]+(idx===L.length-1?' 六十处花园已走到终点，你可以重玩挑战更少步数。':' 下一处失色的角落在等你。'):texts[chapter];$('story').append(t,v);$('garden').replaceChildren();['🌷','🌼','🌻','🌿','🪻','🌺','🪷'].forEach((flower,i)=>{const span=document.createElement('span');span.textContent=flower;span.className='flower'+(i<done?' restored':'');$('garden').append(span)})}

$('export-save').onclick=()=>{const data={version:1,idx,b,history,totalMoves,assisted,recorded,journal};const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='faded-garden-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import-save').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const x=JSON.parse(await f.text());if(x.version!==1||!Number.isInteger(x.idx)||!L[x.idx]||!R.validateBoard(x.b,L[x.idx].colors,4,9)||!Array.isArray(x.history)||!x.history.every(a=>R.validateBoard(a,L[x.idx].colors,4,9))||!Number.isInteger(x.totalMoves)||x.totalMoves<0||!x.journal||typeof x.journal!=='object')throw Error();if(!confirm('导入将覆盖当前存档，是否继续？'))return;idx=x.idx;b=x.b;history=x.history;totalMoves=x.totalMoves;assisted=!!x.assisted;recorded=!!x.recorded;journal=x.journal;busy=false;selected=-1;hints=[];save();draw();$('save-status').textContent='导入成功'}catch{$('save-status').textContent='无法导入：存档格式不正确，原进度已保留'}e.target.value=''};
